html:
{%- from "templates/print_formats/standard_macros.html" import add_header, render_field, print_value, fieldmeta,
	get_width, get_align_class with context -%}

{%- macro render_currency(df, doc) -%}
<div class="row {% if df.bold %}important{% endif %} data-field">
	<div class="col-xs-{{ "9" if df.fieldtype=="Check" else "5" }}
		{%- if doc.align_labels_right %} text-right{%- endif -%}">
		<label>{{ _(df.label, context=df.parent) }}</label>
	</div>
	<div class="col-xs-{{ "3" if df.fieldtype=="Check" else "7" }} value">
		{% if doc.get(df.fieldname) != None -%}
			{{ frappe.utils.fmt_money((doc[df.fieldname])|abs, currency=doc.currency) }}
		{% endif %}
	</div>
</div>
{%- endmacro -%}

{%- macro render_taxes(df, doc) -%}
	{%- set data = doc.get(df.fieldname)[df.start:df.end] -%}
	<div class="row">
		<div class="col-xs-6"></div>
		<div class="col-xs-6">
			{%- for charge in data -%}
				{%- if (charge.tax_amount or doc.flags.print_taxes_with_zero_amount) and (not charge.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}
				<div class="row">
					<div class="col-xs-5 {%- if doc.align_labels_right %} text-right{%- endif -%}">
						<label>{{ charge.get_formatted("description") }}</label></div>
					<div class="col-xs-7 text-right">
						{{ frappe.utils.fmt_money((charge.tax_amount)|abs, currency=doc.currency) }}
					</div>
				</div>
				{%- endif -%}
			{%- endfor -%}
		</div>
	</div>
{%- endmacro -%}

{%- macro render_table(df, doc) -%}
	{%- set table_meta = frappe.get_meta(df.options) -%}
	{%- set data = doc.get(df.fieldname)[df.start:df.end] -%}
	{%- if doc.print_templates and
			doc.print_templates.get(df.fieldname) -%}
		{% include doc.print_templates[df.fieldname] %}
	{%- else -%}
		{%- if data -%}
		{%- set visible_columns = get_visible_columns(doc.get(df.fieldname),
			table_meta, df) -%}
		<div {{ fieldmeta(df) }}>
			<table class="table table-bordered table-condensed">
				<thead>
					<tr>
						<th style="width: 40px" class="table-sr">{{ _("Sr") }}</th>
						{% for tdf in visible_columns %}
						{% if (data and not data[0].flags.compact_item_print) or tdf.fieldname in doc.get(df.fieldname)[0].flags.compact_item_fields %}
							<th style="width: {{ get_width(tdf) }};" class="{{ get_align_class(tdf) }}" {{ fieldmeta(df) }}>
								{{ _(tdf.label) }}</th>
						{% endif %}
						{% endfor %}
					</tr>
				</thead>
				<tbody>
					{% for d in data %}
					<tr>
						<td class="table-sr">{{ d.idx }}</td>
						{% for tdf in visible_columns %}
						{% if not print_settings.compact_item_print or tdf.fieldname in doc.flags.compact_item_fields %}
							<td class="{{ get_align_class(tdf) }}" {{ fieldmeta(df) }}>
								{% if tdf.fieldname == 'qty' %}
									<div class="value">{{ (d[tdf.fieldname])|abs }}</div></td>
								{% elif tdf.fieldtype == 'Currency' %}
									<div class="value">{{ frappe.utils.fmt_money((d[tdf.fieldname])|abs, currency=doc.currency) }}</div></td>
								{% else %}
									{% if doc.child_print_templates %}
										{%- set child_templates = doc.child_print_templates.get(df.fieldname) -%}
											<div class="value">{{ print_value(tdf, d, doc, visible_columns, child_templates) }}</div></td>
										{% else %}
											<div class="value">{{ print_value(tdf, d, doc, visible_columns) }}</div></td>
									{% endif %}
								{% endif %}
						{% endif %}
						{% endfor %}
					</tr>
					{% endfor %}
				</tbody>
			</table>
		</div>
		{%- endif -%}
	{%- endif -%}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>

	{% if print_settings.repeat_header_footer %}
	<div id="footer-html" class="visible-pdf">
		{% if not no_letterhead and footer %}
		<div class="letter-head-footer">
			{{ footer }}
		</div>
		{% endif %}
		<p class="text-center small page-number visible-pdf">
			{{ _("Page {0} of {1}").format('<span class="page"></span>', '<span class="topage"></span>') }}
		</p>
	</div>
	{% endif %}

	{% for section in page %}
    <div class="row section-break">
		{% if section.columns.fields %}
				{%- if doc.print_line_breaks and loop.index != 1 -%}<hr>{%- endif -%}
				{%- if doc.print_section_headings and section.label and section.has_data -%}
				<h4 class='col-sm-12'>{{ _(section.label) }}</h4>
			{% endif %}
		{%- endif -%}
        {% for column in section.columns %}
			<div class="col-xs-{{ (12 / section.columns|len)|int }} column-break">
				{% for df in column.fields %}
					{% if df.fieldname == 'taxes' %}
						{{ render_taxes(df, doc) }}
					{% elif df.fieldtype == 'Currency' %}
						{{ render_currency(df, doc) }}
					{% elif df.fieldtype =='Table' %}
						{{ render_table(df, doc)}}
					{% elif doc[df.fieldname] and df.fieldname != 'total_qty' %}
						{{ render_field(df, doc) }}
					{% endif %}
           		 {% endfor %}
			</div>
        {% endfor %}
    </div>
    {% endfor %}
</div>
{% endfor %}

{%
	const report_columns = report
		.get_columns_for_print()
		.filter(col => !col.hidden);

	if (report_columns.length > 8) {
		frappe.throw(
			__("Too many columns. Export the report and print it using a spreadsheet application.")
		);
	}
%}

<style>
	body, html {
		margin-top: 10px;
		padding: 0;
		width: 100%;
		height: auto;
		font-family: Inter, sans-serif;
		font-size: 14px;
		line-height: 21px;
		color: #171717;
	}

	.title-letter-spacing {
		font-size: 14px;
		font-weight: 600;
		color: #171717;
	}

	.financial-statements-important td {
		font-weight: bold;
	}

	.financial-statements-blank-row td {
		height: 43px;
	}

	.report-meta {
		margin: 10px 0 14px;
		padding: 8px 10px;
		display: flex;
		justify-content: space-between;
		align-items: flex-start;
		gap: 12px;
		font-size: 14px;
		color: #171717;
	}

	.report-meta .left,
	.report-meta .right {
		display: flex;
		flex-direction: column;
	}

	.report-meta strong {
		color: #7c7c7c;
		font-weight: 500;
	}

	.report-subtitle {
		margin: 10px 0 14px;
	}

	.text-center {
		text-align: center;
	}

	.text-right {
		text-align: right;
		font-variant-numeric: tabular-nums;
		white-space: nowrap;
		overflow: hidden;
		text-overflow: ellipsis;
	}

	.text-left {
		text-align: left;
	}

	.text-bold {
		font-weight: 700;
	}

	.text-muted {
		color: #7c7c7c;
	}

	.report-table table {
		width: 100%;
		table-layout: fixed;
		border-collapse: separate;
		border-spacing: 0;
	}

	.report-table th,
	.report-table td {
		padding: 6px 8px;
		font-size: 14px;
		border-bottom: 1px solid #ededed;
	}

	.report-table thead th {
		background: #f8f8f8;
		font-weight: 500;
		color: #7c7c7c;
		border-top: 1px solid #ededed;
		border-bottom: 1px solid #ededed;
	}

	.report-table tbody td.text-left {
		vertical-align: top;
		word-wrap: break-word;
	}

	.report-table thead tr:first-child th:first-child {
		border-left: 1px solid #ededed;
		border-top-left-radius: 10px;
		border-bottom-left-radius: 10px;
	}

	.report-table thead tr:first-child th:last-child {
		border-right: 1px solid #ededed;
		border-top-right-radius: 10px;
		border-bottom-right-radius: 10px;
	}

	.report-table tbody tr:last-child td {
		border-bottom: none;
	}

	.report-table tbody tr {
		height: 43px;
	}

	@media print {
		@page {
			size: A4;
			margin-top: 10mm;
		}

		thead {
			display: table-header-group;
		}

		tr {
			page-break-inside: avoid;
		}
	}
</style>

<div>

	<div class="text-center" style="margin-bottom: 12px;">
		<div class="title-letter-spacing">
			{%= __(report.report_name) %}
		</div>
	</div>

    {% if (subtitle && subtitle.trim()) { %}
        <div class="report-subtitle">
            {{ subtitle }}
        </div>
    {% } else { %}
        <div class="report-meta">
            <div class="left">
                <div>
                    <strong>{%= __("Company") %}:</strong> {%= filters.company %}
                </div>
                <div>
                    <strong>{%= __("Currency") %}:</strong>
                    {%= filters.presentation_currency || erpnext.get_currency(filters.company) %}
                </div>
            </div>

            <div class="right text-right">
                <div>
                    <strong>{%= __("From Date") %}:</strong>
                    {%= frappe.datetime.str_to_user(filters.from_date) %}
                </div>
                <div>
                    <strong>{%= __("To Date") %}:</strong>
                    {%= frappe.datetime.str_to_user(filters.to_date) %}
                </div>
            </div>
        </div>
    {% } %}

	<div class="report-table">
    	<table>
    		<thead>
    			<tr>
    				{% for (let i = 0, l = report_columns.length; i < l; i++) { %}
    					{%
    						const col = report_columns[i];
    						const align = i === 0 ? "text-left" : "text-right";
    						const styling = i === 0 ? "" : "width: 9em";
    					%}
    					<th class="{%= align %}" style= "{%= styling%}">
    						{%= col.label %}
    					</th>
    				{% } %}
    			</tr>
    		</thead>

    		<tbody>
    			{% for (let j = 0, k = data.length; j < k; j++) { %}
    				{%
    					const row = data[j];

    					let row_class = "";
    					if (!(row.parent_account || row.parent_section)) {
    						row_class = "financial-statements-important";
    					}
    					if (!(row.account_name || row.section)) {
    						row_class += " financial-statements-blank-row";
    					}
    				%}

    				<tr class="{%= row_class %}">
    					{% for (let i = 0, l = report_columns.length; i < l; i++) { %}
    						{%
    							const col = report_columns[i];
    							const value = row[col.fieldname];
    							const align = i === 0 ? "text-left" : "text-right";
    						%}

    						<td class="{%= align %}">
    							{% if (i === 0) { %}
    								<span style="padding-left: {%= cint(row.indent) * 2 %}em">
    									{%= String(row.account_name || row.section || "").replace(/^['"]|['"]$/g, "") %}
    								</span>
    							{% } else if (!is_null(value)) { %}
    								{%= frappe.format(value, col, {}, row) %}
    							{% } %}
    						</td>
    					{% } %}
    				</tr>
    			{% } %}
    		</tbody>
    	</table>
    </div>

	<p class="text-right text-muted">
		{%= __("Printed on {0}", [
			frappe.datetime.str_to_user(frappe.datetime.get_datetime_as_string())
		]) %}
	</p>

</div>

